  'inv.proof.hint': {
    de: '„Vom Anbieter angenommen“ belegt, dass die Mail mit genau diesem Anhang an diese Adresse hinausging. Ob sie gelesen wurde, kann ein Mailversand nicht belegen. Adresse und Betreff bleiben sechs Jahre gespeichert.',
    en: '“Accepted by provider” proves that the email with exactly this attachment went out to this address. Whether it was read cannot be proven by email. Address and subject are kept for six years.',
    tr: '“Sağlayıcı tarafından kabul edildi”, e-postanın tam bu ekle bu adrese gönderildiğini kanıtlar. Okunup okunmadığı e-postayla kanıtlanamaz. Adres ve konu altı yıl saklanır.',
    nl: '“Door provider aangenomen” bewijst dat de e-mail met precies deze bijlage naar dit adres is verstuurd. Of hij gelezen is, kan e-mail niet bewijzen. Adres en onderwerp blijven zes jaar bewaard.',
    da: '“Modtaget af udbyder” dokumenterer, at mailen med netop dette bilag blev sendt til denne adresse. Om den er læst, kan e-mail ikke dokumentere. Adresse og emne gemmes i seks år.',
    sv: '”Mottaget av leverantören” visar att mejlet med exakt denna bilaga gick till denna adress. Om det lästs kan e-post inte visa. Adress och ämne sparas i sex år.',
    nb: '«Mottatt av leverandør» viser at e-posten med nøyaktig dette vedlegget gikk til denne adressen. Om den er lest, kan e-post ikke vise. Adresse og emne lagres i seks år.',
    pl: '„Przyjęto przez dostawcę” dowodzi, że e-mail z dokładnie tym załącznikiem wyszedł na ten adres. Czy został przeczytany, e-mail nie dowiedzie. Adres i temat są przechowywane sześć lat.',
    cs: '„Přijato poskytovatelem“ dokládá, že e-mail s přesně touto přílohou odešel na tuto adresu. Zda byl přečten, e-mail doložit nemůže. Adresa a předmět se uchovávají šest let.',
    fr: '« Accepté par le prestataire » prouve que l’e-mail avec exactement cette pièce jointe est parti à cette adresse. Qu’il ait été lu, un e-mail ne peut le prouver. Adresse et objet sont conservés six ans.',
    it: '“Accettato dal fornitore” prova che l’e-mail con esattamente questo allegato è partita verso questo indirizzo. Se sia stata letta, l’e-mail non può provarlo. Indirizzo e oggetto restano salvati sei anni.',
    es: '«Aceptado por el proveedor» prueba que el correo con exactamente este adjunto salió hacia esta dirección. Si se leyó, el correo no puede probarlo. Dirección y asunto se conservan seis años.',
    ru: '«Принято провайдером» подтверждает, что письмо именно с этим вложением ушло на этот адрес. Было ли оно прочитано, почта подтвердить не может. Адрес и тема хранятся шесть лет.',
    uk: '«Прийнято провайдером» підтверджує, що лист саме з цим вкладенням пішов на цю адресу. Чи його прочитано, пошта підтвердити не може. Адресу й тему зберігають шість років.',
    zh: '“服务商已接收”证明带有此附件的邮件已发往该地址。邮件无法证明是否已被阅读。地址和主题保存六年。',
    ko: '“공급자가 수락함”은 바로 이 첨부 파일이 담긴 메일이 이 주소로 발송되었음을 증명합니다. 읽었는지는 메일로 증명할 수 없습니다. 주소와 제목은 6년간 보관됩니다.',
    ar: '«قبله المزوّد» يُثبت أن الرسالة بهذا المرفق تحديدًا أُرسلت إلى هذا العنوان. أما قراءتها فلا يمكن للبريد إثباتها. يُحفظ العنوان والموضوع ست سنوات.',
    pt: '«Aceite pelo fornecedor» comprova que o e-mail com exatamente este anexo saiu para este endereço. Se foi lido, o e-mail não consegue comprovar. Endereço e assunto ficam guardados seis anos.',
    fi: '”Palveluntarjoaja vastaanotti” osoittaa, että viesti juuri tällä liitteellä lähti tähän osoitteeseen. Sitä, onko se luettu, sähköposti ei voi osoittaa. Osoite ja aihe säilytetään kuusi vuotta.',
    is: '„Þjónustuaðili tók við“ sannar að pósturinn með nákvæmlega þessu viðhengi fór á þetta netfang. Hvort hann var lesinn getur tölvupóstur ekki sannað. Netfang og efni eru geymd í sex ár.',
    sk: '„Prijaté poskytovateľom“ dokladá, že e-mail s presne touto prílohou odišiel na túto adresu. Či bol prečítaný, e-mail doložiť nevie. Adresa a predmet sa uchovávajú šesť rokov.',
    sl: '»Ponudnik sprejel« dokazuje, da je e-pošta s točno to prilogo odšla na ta naslov. Ali je bila prebrana, e-pošta ne more dokazati. Naslov in zadeva se hranita šest let.',
    hu: '„Szolgáltató átvette” igazolja, hogy a levél pontosan ezzel a melléklettel erre a címre ment ki. Hogy elolvasták-e, azt e-mail nem tudja igazolni. A címet és a tárgyat hat évig őrizzük.',
    ro: '„Acceptat de furnizor” dovedește că e-mailul cu exact acest atașament a plecat la această adresă. Dacă a fost citit, e-mailul nu poate dovedi. Adresa și subiectul se păstrează șase ani.',
    bg: '„Прието от доставчика“ доказва, че писмото точно с този прикачен файл е изпратено на този адрес. Дали е прочетено, имейлът не може да докаже. Адресът и темата се пазят шест години.',
    hr: '„Prihvatio pružatelj” dokazuje da je poruka s upravo ovim privitkom otišla na ovu adresu. Je li pročitana, e-pošta ne može dokazati. Adresa i predmet čuvaju se šest godina.',
    sr: '„Prihvatio provajder“ dokazuje da je poruka sa upravo ovim prilogom otišla na ovu adresu. Da li je pročitana, e-pošta ne može dokazati. Adresa i predmet čuvaju se šest godina.',
    mk: '„Прифатено од давателот“ докажува дека пораката со токму овој прилог заминала на оваа адреса. Дали е прочитана, е-поштата не може да докаже. Адресата и предметот се чуваат шест години.',
    sq: '“Pranuar nga ofruesi” dëshmon se emaili me pikërisht këtë bashkëngjitje u nis në këtë adresë. Nëse u lexua, emaili nuk mund ta dëshmojë. Adresa dhe subjekti ruhen gjashtë vjet.',
    el: '«Αποδεκτό από τον πάροχο» αποδεικνύει ότι το μήνυμα με ακριβώς αυτό το συνημμένο στάλθηκε σε αυτή τη διεύθυνση. Αν διαβάστηκε, το email δεν μπορεί να το αποδείξει. Διεύθυνση και θέμα φυλάσσονται έξι χρόνια.',
    lt: '„Priimta paslaugų teikėjo“ įrodo, kad laiškas su būtent šiuo priedu išsiųstas šiuo adresu. Ar jis perskaitytas, el. paštas įrodyti negali. Adresas ir tema saugomi šešerius metus.',
    lv: '“Pieņēmis pakalpojumu sniedzējs” apliecina, ka vēstule ar tieši šo pielikumu nosūtīta uz šo adresi. Vai tā izlasīta, e-pasts apliecināt nevar. Adrese un temats tiek glabāti sešus gadus.',
    et: '„Teenusepakkuja võttis vastu“ tõendab, et kiri täpselt selle manusega läks sellele aadressile. Kas seda loeti, e-post tõendada ei saa. Aadressi ja teemat hoitakse kuus aastat.' },
