  'op.hint': {
    de: 'Ohne Mail wird die Stufe nur festgehalten, etwa nach einem Anruf. Nach der dritten Mahnung geht es außerhalb weiter.',
    en: 'Without email the level is only recorded, for example after a phone call. After the third notice, follow-up happens outside the system.',
    tr: 'E-posta olmadan kademe yalnızca kaydedilir, örneğin bir telefon görüşmesinden sonra. Üçüncü ihtardan sonra süreç sistem dışında devam eder.',
    nl: 'Zonder e-mail wordt het niveau alleen vastgelegd, bijvoorbeeld na een telefoongesprek. Na de derde aanmaning gaat het buiten het systeem verder.',
    da: 'Uden e-mail registreres trinnet kun, fx efter et telefonopkald. Efter tredje rykker fortsætter det uden for systemet.',
    sv: 'Utan e-post registreras steget bara, till exempel efter ett samtal. Efter det tredje kravet fortsätter det utanför systemet.',
    nb: 'Uten e-post registreres trinnet bare, for eksempel etter en telefonsamtale. Etter tredje purring fortsetter det utenfor systemet.',
    pl: 'Bez e-maila stopień jest tylko zapisywany, np. po rozmowie telefonicznej. Po trzecim wezwaniu sprawa toczy się poza systemem.',
    cs: 'Bez e-mailu se stupeň jen zaznamená, třeba po telefonátu. Po třetí upomínce se pokračuje mimo systém.',
    fr: 'Sans e-mail, le niveau est seulement enregistré, par exemple après un appel. Après la troisième relance, la suite se fait hors du système.',
    it: 'Senza e-mail il livello viene solo registrato, ad esempio dopo una telefonata. Dopo il terzo sollecito si prosegue fuori dal sistema.',
    es: 'Sin correo, el nivel solo se registra, por ejemplo tras una llamada. Tras el tercer requerimiento se sigue fuera del sistema.',
    ru: 'Без e-mail ступень только фиксируется, например после звонка. После третьего напоминания дело продолжается вне системы.',
    uk: 'Без e-mail ступінь лише фіксується, наприклад після дзвінка. Після третього нагадування справа продовжується поза системою.',
    zh: '不发邮件时只记录级别，例如电话沟通之后。第三次催款后在系统外继续处理。',
    ko: '이메일 없이 기록만 할 수도 있습니다(예: 전화 후). 세 번째 독촉 이후에는 시스템 밖에서 진행합니다.',
    ar: 'بدون بريد إلكتروني يُسجَّل المستوى فقط، مثلًا بعد مكالمة. بعد الإنذار الثالث تستمر المتابعة خارج النظام.',
    pt: 'Sem e-mail o nível é apenas registado, por exemplo após um telefonema. Após o terceiro aviso, segue-se fora do sistema.',
    fi: 'Ilman sähköpostia taso vain kirjataan, esimerkiksi puhelun jälkeen. Kolmannen muistutuksen jälkeen asia jatkuu järjestelmän ulkopuolella.',
    is: 'Án tölvupósts er stigið aðeins skráð, t.d. eftir símtal. Eftir þriðju ítrekun heldur málið áfram utan kerfisins.',
    sk: 'Bez e-mailu sa stupeň len zaznamená, napr. po telefonáte. Po tretej upomienke sa pokračuje mimo systému.',
    sl: 'Brez e-pošte se stopnja le zabeleži, npr. po telefonskem klicu. Po tretjem opominu se nadaljuje zunaj sistema.',
    hu: 'E-mail nélkül a fokozat csak rögzítésre kerül, például egy telefonhívás után. A harmadik felszólítás után a rendszeren kívül folytatódik.',
    ro: 'Fără e-mail, nivelul este doar înregistrat, de exemplu după un apel. După a treia somație se continuă în afara sistemului.',
    bg: 'Без имейл степента само се записва, например след телефонен разговор. След третото напомняне се продължава извън системата.',
    hr: 'Bez e-pošte stupanj se samo bilježi, npr. nakon poziva. Nakon treće opomene nastavlja se izvan sustava.',
    sr: 'Без е-поште степен се само бележи, нпр. после позива. После треће опомене наставља се ван система.',
    mk: 'Без е-пошта степенот само се забележува, на пр. по телефонски разговор. По третата опомена се продолжува надвор од системот.',
    sq: 'Pa email shkalla vetëm regjistrohet, p.sh. pas një telefonate. Pas kujtesës së tretë vazhdohet jashtë sistemit.',
    el: 'Χωρίς email η βαθμίδα απλώς καταχωρίζεται, π.χ. μετά από τηλεφώνημα. Μετά την τρίτη όχληση η συνέχεια γίνεται εκτός συστήματος.',
    lt: 'Be el. laiško lygis tik užfiksuojamas, pvz., po skambučio. Po trečio priminimo tęsiama už sistemos ribų.',
    lv: 'Bez e-pasta pakāpe tiek tikai reģistrēta, piemēram, pēc zvana. Pēc trešā atgādinājuma turpina ārpus sistēmas.',
    et: 'E-postita salvestatakse ainult aste, näiteks pärast telefonikõnet. Pärast kolmandat meeldetuletust jätkatakse väljaspool süsteemi.' },
