  'invoiceSettings.contactHint': {
    de: 'Steht im Fuß jeder Rechnung und in der E-Rechnung. Die IBAN wird mit Prüfziffer geprüft.',
    en: 'Printed in the footer of every invoice and included in the e-invoice. The IBAN is checked against its check digits.',
    tr: 'Her faturanın alt bilgisinde ve e-faturada yer alır. IBAN kontrol basamağıyla doğrulanır.',
    nl: 'Staat in de voettekst van elke factuur en in de e-factuur. De IBAN wordt op het controlegetal gecontroleerd.',
    da: 'Står i bunden af hver faktura og i e-fakturaen. IBAN kontrolleres med kontrolciffer.',
    sv: 'Står i sidfoten på varje faktura och i e-fakturan. IBAN kontrolleras mot kontrollsiffran.',
    nb: 'Står i bunnteksten på hver faktura og i e-fakturaen. IBAN kontrolleres med kontrollsiffer.',
    pl: 'Pojawia się w stopce każdej faktury i w e-fakturze. IBAN jest sprawdzany cyfrą kontrolną.',
    cs: 'Je v patičce každé faktury a v e-faktuře. IBAN se ověřuje kontrolní číslicí.',
    fr: 'Figure en pied de chaque facture et dans la facture électronique. L’IBAN est contrôlé par sa clé.',
    it: 'Compare nel piè di pagina di ogni fattura e nella fattura elettronica. L’IBAN viene verificato con le cifre di controllo.',
    es: 'Aparece al pie de cada factura y en la factura electrónica. El IBAN se comprueba con su dígito de control.',
    ru: 'Печатается внизу каждого счёта и входит в электронный счёт. IBAN проверяется по контрольным цифрам.',
    uk: 'Друкується внизу кожного рахунку та входить до електронного рахунку. IBAN перевіряється за контрольними цифрами.',
    zh: '显示在每张发票的页脚和电子发票中。IBAN 会用校验位进行检查。',
    ko: '모든 청구서 하단과 전자 청구서에 표시됩니다. IBAN은 검증 숫자로 확인합니다.',
    ar: 'تظهر في تذييل كل فاتورة وفي الفاتورة الإلكترونية. يُتحقق من IBAN برقم التحقق.',
    pt: 'Aparece no rodapé de cada fatura e na fatura eletrónica. O IBAN é verificado pelos dígitos de controlo.',
    fi: 'Näkyy jokaisen laskun alatunnisteessa ja e-laskussa. IBAN tarkistetaan tarkisteella.',
    is: 'Birtist neðst á hverjum reikningi og í rafrænum reikningi. IBAN er sannreynt með vartölu.',
    sk: 'Je v päte každej faktúry a v e-faktúre. IBAN sa overuje kontrolnou číslicou.',
    sl: 'Izpisano v nogi vsakega računa in v e-računu. IBAN se preveri s kontrolno številko.',
    hu: 'Minden számla láblécében és az e-számlában szerepel. Az IBAN-t az ellenőrző számmal ellenőrizzük.',
    ro: 'Apare în subsolul fiecărei facturi și în factura electronică. IBAN-ul este verificat prin cifrele de control.',
    bg: 'Стои в долния край на всяка фактура и в електронната фактура. IBAN се проверява по контролните цифри.',
    hr: 'Stoji u podnožju svakog računa i u e-računu. IBAN se provjerava kontrolnim brojem.',
    sr: 'Стоји у подножју сваког рачуна и у е-рачуну. IBAN се проверава контролним бројем.',
    mk: 'Стои во подножјето на секоја фактура и во е-фактурата. IBAN се проверува со контролните цифри.',
    sq: 'Shfaqet në fund të çdo fature dhe në faturën elektronike. IBAN kontrollohet me shifrat e kontrollit.',
    el: 'Εμφανίζεται στο υποσέλιδο κάθε τιμολογίου και στο ηλεκτρονικό τιμολόγιο. Το IBAN ελέγχεται με τα ψηφία ελέγχου.',
    lt: 'Rodoma kiekvienos sąskaitos poraštėje ir e. sąskaitoje. IBAN tikrinamas kontroliniais skaitmenimis.',
    lv: 'Redzams katra rēķina kājenē un e-rēķinā. IBAN tiek pārbaudīts ar kontrolciparu.',
    et: 'On iga arve jaluses ja e-arves. IBAN-i kontrollitakse kontrollnumbriga.' },
