  'invoiceSettings.logoHint': {
    de: 'PNG oder JPEG, höchstens 1 MB. Es steht oben rechts auf jeder Rechnung, die danach ausgestellt wird; ausgestellte Rechnungen behalten ihr Logo.',
    en: 'PNG or JPEG, at most 1 MB. It appears top right on every invoice issued afterwards; issued invoices keep their logo.',
    tr: 'PNG veya JPEG, en fazla 1 MB. Sonrasında kesilen her faturanın sağ üstünde yer alır; kesilmiş faturalar logolarını korur.',
    nl: 'PNG of JPEG, maximaal 1 MB. Het staat rechtsboven op elke factuur die daarna wordt uitgereikt; uitgereikte facturen houden hun logo.',
    da: 'PNG eller JPEG, højst 1 MB. Det står øverst til højre på hver faktura, der udstedes derefter; udstedte fakturaer beholder deres logo.',
    sv: 'PNG eller JPEG, högst 1 MB. Den visas uppe till höger på varje faktura som utfärdas därefter; utfärdade fakturor behåller sin logotyp.',
    nb: 'PNG eller JPEG, maks. 1 MB. Det står øverst til høyre på hver faktura som utstedes etterpå; utstedte fakturaer beholder logoen sin.',
    pl: 'PNG lub JPEG, maks. 1 MB. Pojawia się w prawym górnym rogu każdej faktury wystawionej później; wystawione faktury zachowują swoje logo.',
    cs: 'PNG nebo JPEG, nejvýše 1 MB. Objeví se vpravo nahoře na každé faktuře vystavené poté; vystavené faktury si logo ponechají.',
    fr: 'PNG ou JPEG, 1 Mo au maximum. Il figure en haut à droite de chaque facture émise ensuite ; les factures émises gardent leur logo.',
    it: 'PNG o JPEG, massimo 1 MB. Compare in alto a destra su ogni fattura emessa in seguito; le fatture emesse mantengono il loro logo.',
    es: 'PNG o JPEG, máximo 1 MB. Aparece arriba a la derecha en cada factura emitida después; las facturas emitidas conservan su logotipo.',
    ru: 'PNG или JPEG, не более 1 МБ. Появляется справа вверху на каждом счёте, выставленном после этого; выставленные счета сохраняют свой логотип.',
    uk: 'PNG або JPEG, не більше 1 МБ. З’являється праворуч угорі на кожному рахунку, виставленому після цього; виставлені рахунки зберігають свій логотип.',
    zh: 'PNG 或 JPEG，最大 1 MB。之后开具的每张发票右上角都会显示；已开具的发票保留原标志。',
    ko: 'PNG 또는 JPEG, 최대 1MB. 이후 발행되는 모든 인보이스의 오른쪽 위에 표시되며, 이미 발행된 인보이스는 기존 로고를 유지합니다.',
    ar: 'PNG أو JPEG، بحد أقصى 1 ميغابايت. يظهر أعلى اليمين في كل فاتورة تصدر بعد ذلك؛ وتحتفظ الفواتير الصادرة بشعارها.',
    pt: 'PNG ou JPEG, no máximo 1 MB. Aparece no canto superior direito de cada fatura emitida depois; as faturas emitidas mantêm o seu logótipo.',
    fi: 'PNG tai JPEG, enintään 1 Mt. Se näkyy oikeassa yläkulmassa jokaisessa myöhemmin laaditussa laskussa; laaditut laskut säilyttävät logonsa.',
    is: 'PNG eða JPEG, mest 1 MB. Það birtist efst til hægri á hverjum reikningi sem gefinn er út eftir það; útgefnir reikningar halda sínu merki.',
    sk: 'PNG alebo JPEG, najviac 1 MB. Zobrazí sa vpravo hore na každej faktúre vystavenej potom; vystavené faktúry si logo ponechajú.',
    sl: 'PNG ali JPEG, največ 1 MB. Prikazan je zgoraj desno na vsakem pozneje izdanem računu; izdani računi obdržijo svoj logotip.',
    hu: 'PNG vagy JPEG, legfeljebb 1 MB. Jobb felül jelenik meg minden ezután kiállított számlán; a már kiállított számlák megtartják logójukat.',
    ro: 'PNG sau JPEG, cel mult 1 MB. Apare în dreapta sus pe fiecare factură emisă ulterior; facturile emise își păstrează sigla.',
    bg: 'PNG или JPEG, най-много 1 MB. Появява се горе вдясно на всяка фактура, издадена след това; издадените фактури запазват логото си.',
    hr: 'PNG ili JPEG, najviše 1 MB. Prikazuje se gore desno na svakom računu izdanom nakon toga; izdani računi zadržavaju svoj logotip.',
    sr: 'PNG ili JPEG, najviše 1 MB. Prikazuje se gore desno na svakom računu izdatom posle toga; izdati računi zadržavaju svoj logo.',
    mk: 'PNG или JPEG, најмногу 1 MB. Се појавува горе десно на секоја фактура издадена потоа; издадените фактури го задржуваат логото.',
    sq: 'PNG ose JPEG, deri në 1 MB. Shfaqet lart djathtas në çdo faturë të lëshuar më pas; faturat e lëshuara e ruajnë logon e tyre.',
    el: 'PNG ή JPEG, έως 1 MB. Εμφανίζεται πάνω δεξιά σε κάθε τιμολόγιο που εκδίδεται στη συνέχεια· τα εκδοθέντα τιμολόγια κρατούν το λογότυπό τους.',
    lt: 'PNG arba JPEG, ne daugiau kaip 1 MB. Rodomas viršuje dešinėje kiekvienoje vėliau išrašytoje sąskaitoje; išrašytos sąskaitos išlaiko savo logotipą.',
    lv: 'PNG vai JPEG, ne vairāk kā 1 MB. Tas redzams augšā pa labi katrā vēlāk izrakstītā rēķinā; izrakstītie rēķini saglabā savu logotipu.',
    et: 'PNG või JPEG, kuni 1 MB. See on paremal üleval igal hiljem väljastatud arvel; väljastatud arved jätavad oma logo alles.' },
