  'invoiceSettings.locked': {
    de: 'Unter diesem Kürzel sind schon Rechnungen ausgestellt. Es bleibt, damit keine Nummer zweimal vergeben wird.',
    en: 'Invoices have already been issued under this prefix. It stays, so that no number is issued twice.',
    tr: 'Bu ön ekle zaten fatura kesildi. Hiçbir numara iki kez verilmesin diye değişmez.',
    nl: 'Onder dit prefix zijn al facturen uitgereikt. Het blijft, zodat geen nummer twee keer wordt uitgegeven.',
    da: 'Der er allerede udstedt fakturaer under dette præfiks. Det bliver, så intet nummer bruges to gange.',
    sv: 'Fakturor har redan utfärdats under detta prefix. Det ligger kvar så att inget nummer används två gånger.',
    nb: 'Det er allerede utstedt fakturaer under dette prefikset. Det blir stående, så ingen nummer brukes to ganger.',
    pl: 'Pod tym prefiksem wystawiono już faktury. Pozostaje bez zmian, aby żaden numer nie został nadany dwukrotnie.',
    cs: 'Pod tímto prefixem už byly vystaveny faktury. Zůstává, aby žádné číslo nebylo přiděleno dvakrát.',
    fr: 'Des factures ont déjà été émises sous ce préfixe. Il reste inchangé, afin qu’aucun numéro ne soit attribué deux fois.',
    it: 'Con questo prefisso sono già state emesse fatture. Resta invariato, così nessun numero viene assegnato due volte.',
    es: 'Ya se han emitido facturas con este prefijo. Se mantiene para que ningún número se asigne dos veces.',
    ru: 'С этим префиксом уже выставлены счета. Он остаётся, чтобы ни один номер не был присвоен дважды.',
    uk: 'З цим префіксом уже виставлено рахунки. Він залишається, щоб жоден номер не було присвоєно двічі.',
    zh: '该前缀下已开具发票。前缀保持不变，以免号码重复。',
    ko: '이 접두어로 이미 청구서가 발행되었습니다. 번호가 중복되지 않도록 변경할 수 없습니다.',
    ar: 'صدرت بالفعل فواتير بهذه البادئة. تبقى كما هي حتى لا يتكرر أي رقم.',
    pt: 'Já foram emitidas faturas com este prefixo. Mantém-se, para que nenhum número seja atribuído duas vezes.',
    fi: 'Tällä etuliitteellä on jo laadittu laskuja. Se pysyy, jotta mitään numeroa ei käytetä kahdesti.',
    is: 'Reikningar hafa þegar verið gefnir út undir þessu forskeyti. Það helst, svo ekkert númer sé notað tvisvar.',
    sk: 'Pod týmto prefixom už boli vystavené faktúry. Zostáva, aby žiadne číslo nebolo pridelené dvakrát.',
    sl: 'Pod to predpono so računi že izdani. Ostane, da nobena številka ni dodeljena dvakrat.',
    hu: 'Ezzel az előtaggal már állítottak ki számlát. Marad, hogy egyetlen szám se ismétlődjön.',
    ro: 'Sub acest prefix au fost deja emise facturi. Rămâne, ca niciun număr să nu fie atribuit de două ori.',
    bg: 'С този префикс вече са издадени фактури. Остава, за да не се издаде номер два пъти.',
    hr: 'Pod ovim prefiksom već su izdani računi. Ostaje kako se nijedan broj ne bi dodijelio dvaput.',
    sr: 'Pod ovim prefiksom već su izdati računi. Ostaje kako se nijedan broj ne bi dodelio dvaput.',
    mk: 'Под овој префикс веќе се издадени фактури. Останува, за ниеден број да не се додели двапати.',
    sq: 'Me këtë parashtesë janë lëshuar tashmë fatura. Mbetet, që asnjë numër të mos jepet dy herë.',
    el: 'Έχουν ήδη εκδοθεί τιμολόγια με αυτό το πρόθεμα. Παραμένει, ώστε κανένας αριθμός να μην δοθεί δύο φορές.',
    lt: 'Su šiuo priešdėliu jau išrašyta sąskaitų. Jis lieka, kad joks numeris nebūtų suteiktas dukart.',
    lv: 'Ar šo prefiksu jau ir izrakstīti rēķini. Tas paliek, lai neviens numurs netiktu piešķirts divreiz.',
    et: 'Selle eesliitega on juba arveid väljastatud. See jääb, et ühtki numbrit ei antaks kaks korda.' },
