  'invoiceSettings.paymentTermsHint': {
    de: 'Eine Firma bringt ihr eigenes Ziel mit. Im Rechnungsdialog lässt sich beides je Rechnung ändern.',
    en: 'A company brings its own term. Both can be changed per invoice in the invoice dialog.',
    tr: 'Firmanın kendi vadesi vardır. Fatura penceresinde her ikisi de fatura bazında değiştirilebilir.',
    nl: 'Een bedrijf heeft een eigen termijn. In het factuurvenster zijn beide per factuur aan te passen.',
    da: 'Et firma har sin egen frist. I fakturadialogen kan begge ændres for hver faktura.',
    sv: 'Ett företag har sina egna villkor. I fakturadialogen kan båda ändras per faktura.',
    nb: 'Et firma har sin egen frist. I fakturadialogen kan begge endres per faktura.',
    pl: 'Firma ma własny termin. W oknie faktury oba można zmienić dla każdej faktury.',
    cs: 'Firma má vlastní splatnost. V dialogu faktury lze obojí změnit pro každou fakturu.',
    fr: 'Une entreprise apporte son propre délai. Dans la fenêtre de facturation, les deux se modifient facture par facture.',
    it: 'Un’azienda ha il proprio termine. Nella finestra della fattura entrambi si possono modificare per singola fattura.',
    es: 'Una empresa trae su propio plazo. En el diálogo de factura, ambos se pueden cambiar para cada factura.',
    ru: 'У компании свой срок. В окне счёта оба можно изменить для каждого счёта.',
    uk: 'Компанія має власний строк. У вікні рахунку обидва можна змінити для кожного рахунку.',
    zh: '公司有自己的付款期限。两者都可在开票对话框中按每张发票修改。',
    ko: '회사에는 자체 결제 기한이 있습니다. 청구서 대화 상자에서 청구서마다 둘 다 변경할 수 있습니다.',
    ar: 'للشركة مهلتها الخاصة. ويمكن تغيير الاثنتين لكل فاتورة في نافذة الفاتورة.',
    pt: 'Uma empresa tem o seu próprio prazo. Na janela de faturação, ambos podem ser alterados por fatura.',
    fi: 'Yrityksellä on oma maksuaikansa. Laskuikkunassa molempia voi muuttaa laskukohtaisesti.',
    is: 'Fyrirtæki hefur sinn eigin frest. Í reikningsglugganum má breyta hvoru tveggja fyrir hvern reikning.',
    sk: 'Firma má vlastnú splatnosť. V dialógu faktúry sa dá oboje zmeniť pre každú faktúru.',
    sl: 'Podjetje ima svoj rok. V oknu računa je mogoče oboje spremeniti za vsak račun.',
    hu: 'A cégnek saját határideje van. A számlaablakban mindkettő számlánként módosítható.',
    ro: 'O firmă are propriul termen. În fereastra facturii, ambele se pot modifica pentru fiecare factură.',
    bg: 'Фирмата има собствен срок. В прозореца на фактурата и двата могат да се променят за всяка фактура.',
    hr: 'Tvrtka ima vlastiti rok. U dijalogu računa oboje se može promijeniti za svaki račun.',
    sr: 'Firma ima sopstveni rok. U dijalogu računa oba se mogu promeniti za svaki račun.',
    mk: 'Фирмата има сопствен рок. Во дијалогот на фактурата двата може да се сменат за секоја фактура.',
    sq: 'Kompania ka afatin e vet. Në dritaren e faturës, të dyja mund të ndryshohen për çdo faturë.',
    el: 'Μια εταιρεία έχει τη δική της προθεσμία. Στο παράθυρο τιμολογίου μπορούν να αλλάξουν και τα δύο ανά τιμολόγιο.',
    lt: 'Įmonė turi savo terminą. Sąskaitos lange abu galima keisti kiekvienai sąskaitai.',
    lv: 'Uzņēmumam ir savs termiņš. Rēķina logā abus var mainīt katram rēķinam atsevišķi.',
    et: 'Ettevõttel on oma tähtaeg. Arve aknas saab mõlemat iga arve puhul muuta.' },
