  'inv.cancelConfirm': {
    de: 'Rechnung {number} stornieren? Es entsteht eine Stornorechnung mit eigener Nummer. Die Positionen und Zahlungen stehen danach wieder offen am Folio, und die richtige Rechnung stellst du dort neu aus.',
    en: 'Cancel invoice {number}? A cancellation invoice with its own number is created. The items and payments are then open on the folio again, where you issue the correct invoice.',
    tr: '{number} numaralı fatura iptal edilsin mi? Kendi numarasıyla bir iptal faturası oluşturulur. Kalemler ve ödemeler folyoda yeniden açık olur; doğru faturayı orada yeniden kesersiniz.',
    nl: 'Factuur {number} crediteren? Er ontstaat een creditfactuur met een eigen nummer. De posten en betalingen staan daarna weer open op het folio, waar je de juiste factuur opnieuw uitschrijft.',
    da: 'Annullér faktura {number}? Der oprettes en annulleringsfaktura med eget nummer. Posterne og betalingerne står derefter åbne på folioen igen, hvor du udsteder den rigtige faktura.',
    sv: 'Makulera faktura {number}? En makuleringsfaktura med eget nummer skapas. Posterna och betalningarna ligger sedan öppna på foliot igen, där du utfärdar rätt faktura.',
    nb: 'Annullere faktura {number}? Det opprettes en annulleringsfaktura med eget nummer. Postene og betalingene står deretter åpne på folioen igjen, der du utsteder riktig faktura.',
    pl: 'Anulować fakturę {number}? Powstanie faktura korygująca z własnym numerem. Pozycje i płatności wrócą jako otwarte na folio, gdzie wystawisz właściwą fakturę.',
    cs: 'Stornovat fakturu {number}? Vznikne storno faktura s vlastním číslem. Položky a platby budou poté opět otevřené na foliu, kde vystavíte správnou fakturu.',
    fr: 'Annuler la facture {number} ? Une facture d’annulation avec son propre numéro est créée. Les lignes et paiements redeviennent ouverts sur le folio, où vous émettez la facture correcte.',
    it: 'Stornare la fattura {number}? Viene creata una fattura di storno con numero proprio. Voci e pagamenti tornano aperti sul folio, dove emetti la fattura corretta.',
    es: '¿Anular la factura {number}? Se crea una factura de anulación con número propio. Las partidas y los pagos vuelven a quedar abiertos en el folio, donde emites la factura correcta.',
    ru: 'Сторнировать счёт {number}? Будет создан сторно-счёт с собственным номером. Позиции и платежи снова станут открытыми на фолио, где вы выставите правильный счёт.',
    uk: 'Сторнувати рахунок {number}? Буде створено сторно-рахунок із власним номером. Позиції та платежі знову стануть відкритими на фоліо, де ви виставите правильний рахунок.',
    zh: '冲销发票 {number}？将生成一张带独立编号的冲销发票。之后项目和付款会重新在账单上显示为未结，您可在那里开具正确的发票。',
    ko: '청구서 {number}를 취소할까요? 고유 번호가 있는 취소 청구서가 생성됩니다. 이후 항목과 결제는 폴리오에서 다시 미결 상태가 되며, 그곳에서 올바른 청구서를 발행합니다.',
    ar: 'إلغاء الفاتورة {number}؟ تُنشأ فاتورة إلغاء برقم خاص بها. تعود البنود والمدفوعات مفتوحة على الحساب، وتُصدر الفاتورة الصحيحة من هناك.',
    pt: 'Anular a fatura {number}? É criada uma fatura de anulação com número próprio. Os itens e pagamentos voltam a ficar em aberto no fólio, onde emite a fatura correta.',
    fi: 'Mitätöidäänkö lasku {number}? Syntyy mitätöintilasku omalla numerollaan. Rivit ja maksut ovat sen jälkeen taas avoinna foliolla, jossa laadit oikean laskun.',
    is: 'Ógilda reikning {number}? Ógildingarreikningur með eigin númeri verður til. Liðir og greiðslur verða þá aftur opnar á reikningnum, þar sem þú gefur út réttan reikning.',
    sk: 'Stornovať faktúru {number}? Vznikne storno faktúra s vlastným číslom. Položky a platby budú potom opäť otvorené na fóliu, kde vystavíte správnu faktúru.',
    sl: 'Stornirati račun {number}? Nastane storno račun z lastno številko. Postavke in plačila so nato spet odprti na foliu, kjer izdaš pravi račun.',
    hu: 'Sztornózza a(z) {number} számlát? Saját számú sztornószámla jön létre. A tételek és fizetések ezután ismét nyitottak a folión, ahol kiállítja a helyes számlát.',
    ro: 'Stornați factura {number}? Se creează o factură de stornare cu număr propriu. Pozițiile și plățile redevin deschise pe folio, unde emiteți factura corectă.',
    bg: 'Да се сторнира ли фактура {number}? Създава се сторно фактура със собствен номер. Позициите и плащанията отново стават открити по фолиото, където издавате правилната фактура.',
    hr: 'Stornirati račun {number}? Nastaje storno račun s vlastitim brojem. Stavke i plaćanja zatim su ponovno otvoreni na foliju, gdje izdajete ispravan račun.',
    sr: 'Stornirati račun {number}? Nastaje storno račun sa sopstvenim brojem. Stavke i plaćanja su zatim ponovo otvoreni na foliju, gde izdajete ispravan račun.',
    mk: 'Да се сторнира фактурата {number}? Се создава сторно фактура со сопствен број. Ставките и плаќањата потоа повторно се отворени на фолиото, каде ја издавате точната фактура.',
    sq: 'Të stornohet fatura {number}? Krijohet një faturë stornimi me numër të vetin. Zërat dhe pagesat mbeten sërish të hapura në folio, ku lëshoni faturën e saktë.',
    el: 'Ακύρωση του τιμολογίου {number}; Δημιουργείται ακυρωτικό τιμολόγιο με δικό του αριθμό. Τα στοιχεία και οι πληρωμές ξαναγίνονται ανοιχτά στο folio, όπου εκδίδετε το σωστό τιμολόγιο.',
    lt: 'Stornuoti sąskaitą {number}? Sukuriama storno sąskaita su savo numeriu. Pozicijos ir mokėjimai vėl tampa atviri folio, kur išrašote teisingą sąskaitą.',
    lv: 'Stornēt rēķinu {number}? Tiek izveidots storno rēķins ar savu numuru. Pozīcijas un maksājumi pēc tam atkal ir atvērti folio, kur izrakstāt pareizo rēķinu.',
    et: 'Kas tühistada arve {number}? Luuakse oma numbriga tühistusarve. Read ja maksed on seejärel foliol jälle avatud ning õige arve koostad seal.' },
